/** Every ECON-backed rule group (each ECON key appears exactly once). */
export const SCALAR_GROUPS = { economy: economyRules, depths: depthsRules, surface: surfaceRules, sky: skyRules, orbit: orbitRules, queue: queueRules, movement: movementRules, combat: combatRules, ascent: ascentRules, research: researchRules, signals: signalsRules, spire: spireScalarRules };

/** Durations in a stats row (seconds in the rules, ticks in STATS). */
const STAT_SECONDS = { build: true, cooldown: true, shieldDelay: true };
/** Is stats field `f` a duration (seconds in the rules, ticks in STATS)? */
export const isStatSeconds = (f) => Object.hasOwn(STAT_SECONDS, f);

/** The value of the match rule behind on/off Econ key `key`, from the rules alone (whichever scalar group holds it). */
export function ruleToggle(rules, key) {
  for (const [group, spec] of Object.entries(SCALAR_GROUPS)) {
    for (const [name, row] of Object.entries(spec)) if (row[0] === key) return (rules[group])[name];
  }
  throw new Error(`No match rule for ${key}`);
}

/** Compile rules for the sim. `compileRules(DEFAULT_RULES)` equals ECON, STATS and SPIRE_HP exactly. */
export function compileRules(rules) {
  const econ = { ...ECON };
  const table = econ;
  for (const [group, spec] of Object.entries(SCALAR_GROUPS)) {
    const values = rules[group];
    for (const [key, [k, unit]] of Object.entries(spec)) table[k] = unit === 'sec' ? toTicks(values[key]) : values[key];
  }
  const stats = {};
  for (const kind of Object.keys(STATS)) {
    const row = { ...STATS[kind] };
    const over = kind === 'spire' ? { ...rules.spire, hp: rules.spire.hp.surface } : (rules.stats[kind]);
    for (const f of ['hp', 'shield', 'shieldRegen', 'shieldDelay', 'orbitAcceleration', 'orbitTurnRate', 'speed', 'dmg', 'range', 'cooldown', 'alloy', 'energy', 'build', 'vision']) {
      const v = (over)[f];
      if (typeof v === 'number') row[f] = isStatSeconds(f) ? toTicks(v) : v;
    }
    stats[kind] = row;
  }
  return { econ, stats, spireHp: { ...rules.spire.hp }, timeCap: toTicks(rules.spire.timeCap), sunSpeed: Math.PI / (econ.sunPeriodTicks / TICK_RATE), spires: spirePositions(rules.map.spireInset, rules.map.size) };
}
